H.background();
const w = H.W, hh = H.H;
const n = Math.round(P.n);
const phrase = Math.round(P.phrase) % 4; // pick which verbal phrase to translate
const q = String.fromCharCode(34); // double-quote char for the English phrase
// Phrase bank: words -> algebra, with the operation keyword highlighted.
const bank = [
  { words: q + n + " more than a number" + q,         expr: "x + " + n, op: "more than -> +" },
  { words: q + n + " less than a number" + q,          expr: "x - " + n, op: "less than -> -" },
  { words: q + "the product of " + n + " and a number" + q, expr: n + " * x", op: "product -> *" },
  { words: q + "a number divided by " + n + q,         expr: "x / " + n, op: "divided by -> /" }
];
const cur = bank[phrase];
H.text("Translate words to algebra", 24, 32, { color: H.colors.ink, size: 18, weight: 700 });
H.text("'a number' becomes the variable x; the keyword picks the operation.", 24, 54, { color: H.colors.sub, size: 13 });
H.rect(50, 100, w - 100, 54, { fill: H.colors.panel, stroke: H.colors.grid, width: 1, radius: 10 });
H.text(cur.words, 70, 134, { color: H.colors.ink, size: 20, weight: 600 });
const ay = 175 + 6 * Math.sin(t * 2.5);
H.arrow(w * 0.5, 160, w * 0.5, ay + 14, { color: H.colors.accent2, width: 3 });
H.text(cur.op, w * 0.5 + 24, ay + 6, { color: H.colors.warn, size: 14 });
H.rect(50, 210, w - 100, 60, { fill: "#13243f", stroke: H.colors.accent, width: 2, radius: 10 });
H.text(cur.expr, 70, 250, { color: H.colors.good, size: 26, weight: 700 });
const keys = ["more than -> +", "less than -> -", "product -> *", "quotient -> /"];
for (let i = 0; i < keys.length; i++) {
  const yy = 320 + i * 26;
  const on = i === phrase;
  H.circle(64, yy - 4, 5, { fill: on ? H.colors.warn : H.colors.grid });
  H.text(keys[i], 80, yy, { color: on ? H.colors.ink : H.colors.sub, size: 14, weight: on ? 700 : 400 });
}
H.text("n = " + n + "    phrase #" + (phrase + 1) + "    ->    " + cur.expr, 24, hh - 22, { color: H.colors.sub, size: 14 });
